{
  "packet_id": "H6-T01-1",
  "claim_id": "C064",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C064.component",
    "value": "Evaluation should check that apparent improvement does not consist merely of suppressing bookings.",
    "scope": "An interpretation limit on apparent improvement, not an assertion that bookings have been suppressed.",
    "provenance": {
      "refs": [
        {
          "source_id": "P029",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P029 explicitly supplies the booking-suppression check and its limitation to apparent improvement."
    }
  },
  "signal_basis": {
    "component_id": "C064.signal_basis",
    "value": "Continue measuring late-start proportions, delay minutes and booking denominators through the trial, observing apparent sustained improvement across repeated periods.",
    "scope": "Trial evaluation using repeated measurements; apparent improvement alone does not establish whether bookings were suppressed.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        },
        {
          "source_id": "P029",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify the measurements, continued trial observation, sustained-improvement signal and booking-suppression qualification."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C064.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported without establishing a further empirical relation."
    }
  },
  "rationale": "Suppressing bookings can reduce recorded delay burden or change which bookings contribute to late-start rates. Repeated apparent improvement therefore licenses checking whether the measured gain merely reflects suppressed bookings. The claim requires a check, not a finding that suppression occurred.",
  "uncertainty": "Whether bookings were actually suppressed remains undetermined; this does not weaken the warrant for checking.",
  "anomalies": []
}
